span.t-attf-class:
badge-{{
                                            appointment.state == 'confirmed' ? 'warning' :
                                            appointment.state == 'checked_in' ? 'info' :
                                            appointment.state == 'in_progress' ? 'primary' :
                                            appointment.state == 'completed' ? 'success' :
                                            appointment.state == 'cancelled' ? 'danger' :
                                            'secondary'
                                        }}

template.script:
(function() {
    'use strict';

    var selectedService = null;
    var selectedStaff = null;
    var selectedDate = null;

    window.selectService = function(element) {
        // Remove previous selection
        document.querySelectorAll('.service-card').forEach(function(c) {
            c.classList.remove('selected');
        });
        element.classList.add('selected');
        selectedService = element.dataset.serviceId;
        var nextBtn = document.getElementById('step1_next');
        if (nextBtn) nextBtn.disabled = false;

        // Update confirmation
        var serviceName = element.querySelector('.card-title').textContent;
        var price = element.dataset.price;
        var duration = element.dataset.duration;

        var confirmService = document.getElementById('confirm_service');
        var confirmDuration = document.getElementById('confirm_duration');
        var confirmPrice = document.getElementById('confirm_price');

        if (confirmService) confirmService.textContent = serviceName;
        if (confirmDuration) confirmDuration.textContent = duration + ' minutes';
        if (confirmPrice) confirmPrice.textContent = '$' + price;
    };

    window.selectStaff = function(element) {
        document.querySelectorAll('.staff-card').forEach(function(c) {
            c.classList.remove('selected');
        });
        element.classList.add('selected');
        selectedStaff = element.dataset.staffId;
        var nextBtn = document.getElementById('step2_next');
        if (nextBtn) nextBtn.disabled = false;

        // Update confirmation
        var staffName = element.querySelector('.card-title').textContent;
        var confirmStaff = document.getElementById('confirm_staff');
        if (confirmStaff) confirmStaff.textContent = staffName;
    };

    window.goToStep = function(step) {
        // Hide all steps
        for (var i = 1; i <= 4; i++) {
            var el = document.getElementById('step' + i + '_content');
            if (el) el.style.display = 'none';
        }

        // Show selected step
        var target = document.getElementById('step' + step + '_content');
        if (target) target.style.display = 'block';

        // Update step indicators
        document.querySelectorAll('.step').forEach(function(s) {
            s.classList.remove('active', 'completed');
            var stepNum = parseInt(s.id.replace('step', ''));
            if (stepNum === step) {
                s.classList.add('active');
            } else if (stepNum step) {
                s.classList.add('completed');
            }
        });
    };

    window.checkAvailability = function() {
        var date = document.getElementById('booking_date').value;
        var time = document.getElementById('booking_time').value;
        var statusEl = document.getElementById('availability_status');
        var nextBtn = document.getElementById('step3_next');

        if (!date || !time) {
            if (statusEl) {
                statusEl.className = 'alert alert-warning';
                statusEl.innerHTML = Please select both date and time';
            }
            if (nextBtn) nextBtn.disabled = true;
            return;
        }

        var datetime = date + 'T' + time + ':00';
        selectedDate = datetime;

        // Update confirmation
        var dateObj = new Date(date + 'T' + time);
        var confirmDatetime = document.getElementById('confirm_datetime');
        if (confirmDatetime) {
            confirmDatetime.textContent =
                dateObj.toLocaleDateString('en-US', {
                    weekday: 'long',
                    year: 'numeric',
                    month: 'long',
                    day: 'numeric'
                }) + ' at ' + dateObj.toLocaleTimeString('en-US', {
                    hour: '2-digit',
                    minute: '2-digit'
                });
        }

        // Check availability via AJAX
        var xhr = new XMLHttpRequest();
        xhr.open('POST', '/salon/booking/check_availability', true);
        xhr.setRequestHeader('Content-Type', 'application/json');
        xhr.onload = function() {
            if (xhr.status === 200) {
                var response = JSON.parse(xhr.responseText);
                if (statusEl) {
                    if (response.available) {
                        statusEl.className = 'alert alert-success';
                        statusEl.innerHTML = response.message;
                        if (nextBtn) nextBtn.disabled = false;
                    } else {
                        statusEl.className = 'alert alert-danger';
                        statusEl.innerHTML = response.message;
                        if (nextBtn) nextBtn.disabled = true;
                    }
                }
            }
        };
        xhr.send(JSON.stringify({
            employee_id: selectedStaff,
            appointment_date: datetime,
            duration: 30
        }));
    };

    window.submitBooking = function() {
        var name = document.getElementById('customer_name').value;
        var phone = document.getElementById('customer_phone').value;
        var email = document.getElementById('customer_email').value;
        var requests = document.getElementById('special_requests').value;

        if (!name || !phone) {
            alert('Please fill in your name and phone number.');
            return;
        }

        var data = {
            customer_name: name,
            customer_phone: phone,
            customer_email: email,
            service_ids: [selectedService],
            employee_id: selectedStaff,
            appointment_date: selectedDate,
            special_requests: requests
        };

        var xhr = new XMLHttpRequest();
        xhr.open('POST', '/salon/booking/create', true);
        xhr.setRequestHeader('Content-Type', 'application/json');
        xhr.onload = function() {
            if (xhr.status === 200) {
                var response = JSON.parse(xhr.responseText);
                if (response.success) {
                    alert('✅ ' + response.message + '\nAppointment #: ' + response.appointment_number);
                    window.location.href = '/my/appointments';
                } else {
                    alert('❌ Error: ' + response.message);
                }
            }
        };
        xhr.send(JSON.stringify(data));
    };

    // Set minimum date to today and add event listeners
    document.addEventListener('DOMContentLoaded', function() {
        var dateInput = document.getElementById('booking_date');
        var timeInput = document.getElementById('booking_time');

        if (dateInput) {
            // Set min date to today
            var today = new Date().toISOString().split('T')[0];
            dateInput.setAttribute('min', today);
            dateInput.addEventListener('change', window.checkAvailability);
        }
        if (timeInput) {
            timeInput.addEventListener('change', window.checkAvailability);
        }
    });

})();
